def paginate(items,page,size):
    if not items:
        return {items:[], total:0, pages:0}
    if not isinstance(page, int) or not isinstance(size, int):
        raise ValueError("page and size must be integers")
    if size < 1:
        raise ValueError("size must be a positive integer")
    total = len(items)
    pages = 0
    start = 0
    while start < total:
        end = start + size
        if end > total:
            end = total
        pages += 1
        start = end
    result = {"items":[], "total":total, "pages":pages}
    for p in range(1, pages + 1):
        if p >= pages:
            break
        items_in_page = items[start:start + size]
        start += size
        result["items"].append(items_in_page)
    return result

